// Maps normalized world-atlas (Natural Earth) feature names to our ISO
// 3166-1 alpha-2 codes. Generated by matching node_modules/world-atlas's
// countries-110m.json against lib/countries.js — see git history for the
// matching script if this ever needs regenerating against a new atlas
// version. Territories with no alpha-2 in our country list (Antarctica,
// Greenland, Western Sahara, disputed regions, etc.) are intentionally
// absent and render as unmapped/gray on the map.
export const WORLD_ATLAS_NAME_TO_CODE = {"fiji":"FJ","tanzania":"TZ","canada":"CA","unitedstatesofamerica":"US","kazakhstan":"KZ","uzbekistan":"UZ","papuanewguinea":"PG","indonesia":"ID","argentina":"AR","chile":"CL","demrepcongo":"CD","somalia":"SO","kenya":"KE","sudan":"SD","chad":"TD","haiti":"HT","dominicanrep":"DO","russia":"RU","bahamas":"BS","norway":"NO","timorleste":"TL","southafrica":"ZA","lesotho":"LS","mexico":"MX","uruguay":"UY","brazil":"BR","bolivia":"BO","peru":"PE","colombia":"CO","panama":"PA","costarica":"CR","nicaragua":"NI","honduras":"HN","elsalvador":"SV","guatemala":"GT","belize":"BZ","venezuela":"VE","guyana":"GY","suriname":"SR","france":"FR","ecuador":"EC","jamaica":"JM","cuba":"CU","zimbabwe":"ZW","botswana":"BW","namibia":"NA","senegal":"SN","mali":"ML","mauritania":"MR","benin":"BJ","niger":"NE","nigeria":"NG","cameroon":"CM","togo":"TG","ghana":"GH","ctedivoire":"CI","guinea":"GN","guineabissau":"GW","liberia":"LR","sierraleone":"SL","burkinafaso":"BF","centralafricanrep":"CF","congo":"CG","gabon":"GA","eqguinea":"GQ","zambia":"ZM","malawi":"MW","mozambique":"MZ","eswatini":"SZ","angola":"AO","burundi":"BI","israel":"IL","lebanon":"LB","madagascar":"MG","palestine":"PS","gambia":"GM","tunisia":"TN","algeria":"DZ","jordan":"JO","unitedarabemirates":"AE","qatar":"QA","kuwait":"KW","iraq":"IQ","oman":"OM","vanuatu":"VU","cambodia":"KH","thailand":"TH","laos":"LA","myanmar":"MM","vietnam":"VN","northkorea":"KP","southkorea":"KR","mongolia":"MN","india":"IN","bangladesh":"BD","bhutan":"BT","nepal":"NP","pakistan":"PK","afghanistan":"AF","tajikistan":"TJ","kyrgyzstan":"KG","turkmenistan":"TM","iran":"IR","syria":"SY","armenia":"AM","sweden":"SE","belarus":"BY","ukraine":"UA","poland":"PL","austria":"AT","hungary":"HU","moldova":"MD","romania":"RO","lithuania":"LT","latvia":"LV","estonia":"EE","germany":"DE","bulgaria":"BG","greece":"GR","turkey":"TR","albania":"AL","croatia":"HR","switzerland":"CH","luxembourg":"LU","belgium":"BE","netherlands":"NL","portugal":"PT","spain":"ES","ireland":"IE","solomonis":"SB","newzealand":"NZ","australia":"AU","srilanka":"LK","china":"CN","taiwan":"TW","italy":"IT","denmark":"DK","unitedkingdom":"GB","iceland":"IS","azerbaijan":"AZ","georgia":"GE","philippines":"PH","malaysia":"MY","brunei":"BN","slovenia":"SI","finland":"FI","slovakia":"SK","czechia":"CZ","eritrea":"ER","japan":"JP","paraguay":"PY","yemen":"YE","saudiarabia":"SA","cyprus":"CY","morocco":"MA","egypt":"EG","libya":"LY","ethiopia":"ET","djibouti":"DJ","uganda":"UG","rwanda":"RW","bosniaandherz":"BA","macedonia":"MK","serbia":"RS","montenegro":"ME","kosovo":"XK","trinidadandtobago":"TT","ssudan":"SS"};

export function normName(s) {
  return s.toLowerCase().replace(/[^a-z]/g, "");
}

export function codeForAtlasName(name) {
  return WORLD_ATLAS_NAME_TO_CODE[normName(name)] || null;
}
